#!/usr/bin/env node
/**
 * Bundles C1's in-app legal copies (web/app-docs/privacy.md, terms.md,
 * delete-account.md) into src/modules/legal/generated/legalDocs.ts.
 *
 * Source (Lead, Nov 1 2026): branch phase/c1-compliance, commit e78a01a or
 * newer. The commit and each file's git blob SHA are pinned below.
 *
 *   node scripts/build-legal.mjs --from <dir>   regenerate from a folder
 *   node scripts/build-legal.mjs --check        verify (used by `npm run verify`):
 *     - the generated file matches its own pinned hashes (not hand-edited);
 *     - if web/app-docs/ exists in this checkout (after C1 merges), its files
 *       must be the pinned ones; otherwise C1 changed them -> re-run --from.
 */
import { Buffer } from 'node:buffer';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(root, 'src/modules/legal/generated/legalDocs.ts');
const SOURCE = { branch: 'phase/c1-compliance', commit: 'e78a01a899d6ba47a7858408607b71a50bcf3706', path: 'web/app-docs' };
const DOCS = [
  { id: 'privacy', file: 'privacy.md', title: 'Privacy Policy' },
  { id: 'terms', file: 'terms.md', title: 'Terms of Use' },
  { id: 'delete-account', file: 'delete-account.md', title: 'Delete your account' },
];

const gitBlob = (buf) => createHash('sha1').update(`blob ${buf.length}\0`).update(buf).digest('hex');
const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

function render(dir) {
  const docs = DOCS.map((d) => {
    const buf = readFileSync(join(dir, d.file));
    return { ...d, markdown: buf.toString('utf8'), blob: gitBlob(buf), sha256: sha256(buf) };
  });
  const body = docs
    .map((d) => `  ${JSON.stringify(d.id)}: {\n    title: ${JSON.stringify(d.title)},\n    file: ${JSON.stringify(d.file)},\n    gitBlob: '${d.blob}',\n    sha256: '${d.sha256}',\n    markdown: ${JSON.stringify(d.markdown)},\n  },`)
    .join('\n');
  return `// GENERATED by scripts/build-legal.mjs. Do not edit: run \`node scripts/build-legal.mjs --from <dir>\`.\n// Source: ${SOURCE.branch} @ ${SOURCE.commit} (${SOURCE.path}).\nexport const LEGAL_SOURCE = ${JSON.stringify(SOURCE)} as const;\n\nexport const LEGAL_DOCS = {\n${body}\n} as const;\n`;
}

const args = process.argv.slice(2);
if (args[0] === '--from') {
  writeFileSync(OUT, render(args[1]));
  console.log(`Wrote ${OUT}`);
} else if (args[0] === '--check') {
  const text = readFileSync(OUT, 'utf8');
  let failed = false;
  for (const d of DOCS) {
    const m = new RegExp(`${JSON.stringify(d.id).replace(/[-]/g, '\\-')}: \\{[\\s\\S]*?gitBlob: '([0-9a-f]+)',\\s*sha256: '([0-9a-f]+)',\\s*markdown: ("(?:[^"\\\\]|\\\\.)*")`).exec(text);
    if (!m) { console.error(`legal: ${d.id} missing`); failed = true; continue; }
    const md = Buffer.from(JSON.parse(m[3]), 'utf8');
    if (gitBlob(md) !== m[1] || sha256(md) !== m[2]) { console.error(`legal: ${d.id} was edited by hand`); failed = true; }
    const live = join(root, SOURCE.path, d.file);
    if (existsSync(live) && gitBlob(readFileSync(live)) !== m[1]) {
      console.error(`legal: ${SOURCE.path}/${d.file} changed since ${SOURCE.commit.slice(0, 7)}; run node scripts/build-legal.mjs --from ${SOURCE.path} and update SOURCE.commit`);
      failed = true;
    }
  }
  if (failed) process.exit(1);
  console.log(`Legal copies OK (pinned to ${SOURCE.branch} @ ${SOURCE.commit.slice(0, 7)}).`);
} else {
  console.error('usage: build-legal.mjs --from <dir> | --check');
  process.exit(2);
}
